    const postprocessors = config.postprocessors || [];
    if (postprocessors.length === 0) {
        console.log("\nℹ️  No postprocessors found in configuration.\n");
        await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
        return;
    }
